"""運用日の前日が休みだったかを判定する。

休み明けは躯体に熱が残り、同じ外気温でも予冷が延びる。前日が土日・祝日・
会社休業日のいずれかなら「休み明け」として扱う。

祝日は法令どおりの計算で求める（振替休日・国民の休日を含む）。会社休業日は
このサイトの運用に合わせた決め打ちなので、実際のカレンダーと違う年がありうる。
最終的な区分は画面のラジオで人が上書きできる。
"""

from __future__ import annotations

import datetime as dt

ONE_DAY = dt.timedelta(days=1)

# 会社休業日。サイト固有の運用であり、法定祝日ではない。
SUMMER_CLOSURE = ((8, 13), (8, 16))
YEAR_END_CLOSURE = ((12, 29), (1, 3))

_FIXED_HOLIDAYS = {
    (1, 1): "元日",
    (2, 11): "建国記念の日",
    (2, 23): "天皇誕生日",
    (4, 29): "昭和の日",
    (5, 3): "憲法記念日",
    (5, 4): "みどりの日",
    (5, 5): "こどもの日",
    (8, 11): "山の日",
    (11, 3): "文化の日",
    (11, 23): "勤労感謝の日",
}

# ハッピーマンデー: (月, 第n月曜) -> 名称
_HAPPY_MONDAYS = {
    (1, 2): "成人の日",
    (7, 3): "海の日",
    (9, 3): "敬老の日",
    (10, 2): "スポーツの日",
}


def _equinox_day(year: int, month: int) -> int | None:
    """春分・秋分の日を求める（1980〜2099年の近似式）。

    官報で確定するのは前年2月なので、遠い将来の年は1日ずれる可能性がある。
    """
    if not 1980 <= year <= 2099:
        return None
    base = {3: 20.8431, 9: 23.2488}.get(month)
    if base is None:
        return None
    return int(base + 0.242194 * (year - 1980) - (year - 1980) // 4)


def _statutory_holiday_name(day: dt.date) -> str:
    """法定の祝日名を返す。祝日でなければ空文字。振替休日は含まない。"""
    name = _FIXED_HOLIDAYS.get((day.month, day.day))
    if name:
        return name

    if day.weekday() == 0:
        nth = (day.day - 1) // 7 + 1
        name = _HAPPY_MONDAYS.get((day.month, nth))
        if name:
            return name

    if day.day == _equinox_day(day.year, day.month):
        return "春分の日" if day.month == 3 else "秋分の日"

    return ""


def _substitute_holiday_name(day: dt.date) -> str:
    """振替休日・国民の休日にあたるかを返す。該当しなければ空文字。"""
    if _statutory_holiday_name(day):
        return ""

    # 振替休日: 日曜と重なった祝日から後ろへ、祝日でない最初の日まで送る。
    cursor = day - ONE_DAY
    while _statutory_holiday_name(cursor):
        if cursor.weekday() == 6:
            return "振替休日"
        cursor -= ONE_DAY

    # 国民の休日: 祝日に前後を挟まれた平日。
    sandwiched = _statutory_holiday_name(day - ONE_DAY) and _statutory_holiday_name(day + ONE_DAY)
    if day.weekday() != 6 and sandwiched:
        return "国民の休日"

    return ""


def national_holiday_name(day: dt.date) -> str:
    """国民の祝日（振替休日・国民の休日を含む）の名称。祝日でなければ空文字。"""
    return _statutory_holiday_name(day) or _substitute_holiday_name(day)


def _closure_name(day: dt.date) -> str:
    """会社休業日の名称。休業日でなければ空文字。"""
    month, d = day.month, day.day
    if SUMMER_CLOSURE[0] <= (month, d) <= SUMMER_CLOSURE[1]:
        return "夏季休業（お盆）"
    if (month, d) >= YEAR_END_CLOSURE[0] or (month, d) <= YEAR_END_CLOSURE[1]:
        return "年末年始休業"
    return ""


def is_japanese_holiday(day: dt.date) -> tuple[bool, str]:
    """その日が休み（土日・祝日・会社休業日）かどうかと、その理由を返す。"""
    # 祝日名のほうが理由として具体的なので、休業期間と重なる日は祝日名を優先する。
    holiday = national_holiday_name(day)
    if holiday:
        return True, holiday

    closure = _closure_name(day)
    if closure:
        return True, closure

    if day.weekday() == 6:
        return True, "日曜日"
    if day.weekday() == 5:
        return True, "土曜日"

    return False, ""


def check_after_offday(target_date: dt.date) -> tuple[bool, str]:
    """運用日の前日が休みかどうかを判定する。

    戻り値: (休み明けフラグ, 画面に出す理由文)
    """
    previous = target_date - ONE_DAY
    is_off, reason = is_japanese_holiday(previous)

    if not is_off:
        return False, "前日は通常営業日です（通常平日モード）"

    if target_date.weekday() == 0:
        return True, "月曜日のため前日（土日）が休日です（躯体蓄熱あり）"

    return True, (
        f"前日（{previous.month}/{previous.day}）が{reason}のため休日明けです（躯体蓄熱あり）"
    )

