"""受領したデータの健全性チェック。

実データはダミーデータと同じ形とはかぎらない。列名、粒度、期間、欠測、単位、
センサの生死のいずれもずれうる。分析を回す前にここで洗い出し、
「気づかないまま間違った数字を出す」ことを防ぐ。

警告は落とすためのものではなく、確認するためのもの。
どれも「これはおかしい」ではなく「これを確かめろ」という意味である。
"""

from __future__ import annotations

from dataclasses import dataclass, field

import numpy as np
import pandas as pd

from hvac.energy import sampling_interval_hours
from hvac.io import (
    find_power_columns,
    map_outdoor_columns,
    map_room_columns,
)

# 室温として現実的な範囲。これを外れたらセンサ異常か単位違いを疑う。
PLAUSIBLE_ROOM_RANGE = (-10.0, 50.0)
PLAUSIBLE_OUTDOOR_RANGE = (-30.0, 55.0)
PLAUSIBLE_HUMIDITY_RANGE = (0.0, 100.0)
# チラー電力[kW]の上限の目安。桁が違えば W 単位で入っている可能性がある。
PLAUSIBLE_POWER_MAX_KW = 2000.0

# 起動時刻を分単位で読むのに必要な粒度。1時間粒度では立ち上がりを追えない。
MAX_INTERVAL_FOR_STARTUP_MIN = 10.0

# 同じ値がこの割合以上続いたら、センサが張り付いている可能性がある。
STUCK_RATIO = 0.5

# 記録の刻みがこれより粗いと、到達判定の許容幅（既定0.5℃）に効いてくる。
QUANTIZATION_WARN_STEP = 0.25

# 始業前に閾値を何回またいだらチャタリングとみなすか。
# 立ち上がりがきれいなら、またぐのは1回だけである。
CHATTERING_CROSSINGS = 6


@dataclass
class DataReport:
    """1つのデータフレームの素性。"""

    name: str
    rows: int
    columns: int
    start: pd.Timestamp | None
    end: pd.Timestamp | None
    interval_minutes: float
    coverage_ratio: float
    duplicated_rows: int
    warnings: list[str] = field(default_factory=list)

    def as_row(self) -> dict:
        return {
            "データ": self.name,
            "行数": self.rows,
            "列数": self.columns,
            "開始": self.start,
            "終了": self.end,
            "粒度 [分]": round(self.interval_minutes, 2),
            "充足率 [%]": round(self.coverage_ratio * 100.0, 1),
            "重複時刻": self.duplicated_rows,
            "警告": len(self.warnings),
        }


def _coverage_ratio(frame: pd.DataFrame, interval_minutes: float) -> float:
    """期間に対して実際に何割の時刻が入っているか。欠測の見当をつける。"""
    if len(frame) < 2 or interval_minutes <= 0:
        return 1.0
    span_minutes = (frame.index.max() - frame.index.min()).total_seconds() / 60.0
    expected = span_minutes / interval_minutes + 1
    return min(len(frame) / expected, 1.0) if expected > 0 else 1.0


def _stuck_columns(frame: pd.DataFrame, columns: list) -> list[str]:
    """値がほとんど動かない列。センサの張り付きか、未接続を疑う。

    設定温度や待機中の電力は動かないのが正常なので、この検査にはかけない。
    正常な値まで警告に挙げると、警告そのものが読まれなくなる。
    """
    stuck = []
    for column in columns:
        values = frame[column].dropna()
        if len(values) < 10:
            continue
        top = values.value_counts(normalize=True)
        if not top.empty and top.iloc[0] >= STUCK_RATIO:
            stuck.append(f"{column}（{top.index[0]} が {top.iloc[0] * 100:.0f}%）")
    return stuck


def _dead_columns(frame: pd.DataFrame, columns: list) -> list[str]:
    """全期間で1つの値しか取らない列。動かないのが正常な列でもこれは異常。"""
    return [str(c) for c in columns if frame[c].dropna().nunique() <= 1]


def quantization_step(values: pd.Series) -> float | None:
    """記録の刻み幅。刻みが見つからなければ None。

    BEMSは室温を 0.5℃ 刻みで記録することがある。刻みが到達判定の許容幅に
    近いと、「到達した瞬間」が刻みの分だけずれ、予冷時間が階段状になる。
    """
    unique = np.unique(np.round(values.dropna().to_numpy(dtype=float), 6))
    if len(unique) < 3:
        return None

    diffs = np.diff(unique)
    diffs = diffs[diffs > 1e-9]
    if len(diffs) == 0:
        return None

    step = float(np.min(diffs))
    ratios = diffs / step
    # 値の差がすべて最小刻みの整数倍なら、その刻みで量子化されている。
    # ノイズが乗っていれば整数倍にはならないので、この検査は通らない。
    if np.allclose(ratios, np.round(ratios), atol=0.01):
        return step
    return None


def _quantized_columns(frame: pd.DataFrame, columns: list) -> list[str]:
    found = []
    for column in columns:
        step = quantization_step(frame[column])
        if step is not None and step >= QUANTIZATION_WARN_STEP:
            found.append(f"{column}（{step:g} 刻み）")
    return found


def threshold_crossings(series: pd.Series, threshold_ratio: float = 0.2) -> int:
    """待機とピークの間に引いた閾値を、何回またいだか。"""
    clean = series.dropna()
    if clean.empty:
        return 0
    standby = clean.quantile(0.05)
    peak = clean.max()
    if peak - standby < 1e-9:
        return 0
    above = clean > (standby + (peak - standby) * threshold_ratio)
    return int((above != above.shift()).sum())


def check_startup_stability(
    power: pd.DataFrame, business_hour: int = 8, threshold_ratio: float = 0.2
) -> list[str]:
    """立ち上がりが閾値付近で震えていないかを見る。

    低出力で長く運転してから本格稼働に入る日は、電力が閾値の上下を往復し、
    「一定時間continuously超えた最初の時刻」を満たすのが遅れる。
    その日は起動検出が実際より遅くなり、「起動時点で既に設定温度に達していた」
    ように見えてしまう。
    """
    columns = find_power_columns(power)
    if not columns:
        return []

    total = power[columns].sum(axis=1)
    morning = total[total.index.hour < business_hour]
    if morning.empty:
        return []

    noisy = []
    for day, series in morning.groupby(morning.index.date):
        crossings = threshold_crossings(series, threshold_ratio)
        if crossings >= CHATTERING_CROSSINGS:
            noisy.append((day, crossings))

    if not noisy:
        return []

    listed = ", ".join(f"{day}（{count}回）" for day, count in noisy[:8])
    more = " ほか" if len(noisy) > 8 else ""
    return [
        f"始業前に電力が起動判定の閾値を何度もまたぐ日が {len(noisy)} 日ある: {listed}{more}。"
        "低出力運転が続いてから本格稼働に入ると起こる。"
        "その日は起動検出が実際より遅くなり、予冷時間が短く見える。"
        "日別の電力波形（ノートブック 01）で検出時刻を目視確認すること。"
    ]


def describe_frame(name: str, frame: pd.DataFrame, kind: str = "") -> DataReport:
    """1つのデータフレームを点検する。`kind` は room / outdoor / power。"""
    warnings: list[str] = []

    if frame.empty:
        return DataReport(name, 0, 0, None, None, 0.0, 0.0, 0, ["データが空である。"])

    # 列の役割で検査を分ける。設定温度と電力は動かない時間があって当たり前。
    if kind == "room":
        measured, expected_constant = map_room_columns(frame)
        measured_columns = list(measured.values())
        constant_columns = list(expected_constant.values())
