    payload = _forecast_payload()
    payload["hourly"]["time"].pop()

    with pytest.raises(WeatherAPIError, match="24時間分"):
        fetch_hourly_forecast(
            _location(),
            dt.date(2026, 8, 28),
            opener=_opener(payload),
        )


def test_APIエラーを合成予報へ置き換えない():
    with pytest.raises(WeatherAPIError, match="対象日は予報範囲外"):
        fetch_hourly_forecast(
            _location(),
            dt.date(2026, 9, 30),
            opener=_opener({"error": True, "reason": "対象日は予報範囲外"}),
        )

